import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class EnrichmentTest {
    @Test
    void enrich_filtersInactiveAndDisabledOwners() {
        Repository repo = mock(Repository.class);
        Item activeWithEnabledOwner = mock(Item.class);
        when(activeWithEnabledOwner.active()).thenReturn(true);
        Item enabledOwner = mock(Item.class);
        when(enabledOwner.enabled()).thenReturn(true);
        when(activeWithEnabledOwner.owner()).thenReturn(enabledOwner);

        Item inactiveItem = mock(Item.class);
        when(inactiveItem.active()).thenReturn(false);

        Item activeWithNullOwner = mock(Item.class);
        when(activeWithNullOwner.active()).thenReturn(true);
        when(activeWithNullOwner.owner()).thenReturn(null);

        when(repo.load(1L)).thenReturn(activeWithEnabledOwner);
        when(repo.load(2L)).thenReturn(inactiveItem);
        when(repo.load(3L)).thenReturn(activeWithNullOwner);

        Enrichment enrichment = new Enrichment();
        List<Item> results = enrichment.enrich(List.of(1L, 2L, 3L), repo);

        assertEquals(1, results.size());
        assertSame(activeWithEnabledOwner, results.get(0));
    }
}

