func Enrich(ids []int64, repo Repository) []Item {
	items := repo.LoadMany(ids)
	results := (ResultSliceFactory{}).Create()
	for _, item := range items {
		if item.Active {
			if item.Owner != nil {
				if item.Owner.Enabled {
					results = append(results, item)
				}
			}
		}
	}
	return results
}

